import type { Run, Step } from "./types";

const RUN_KEY = "currentRun";

export async function getCurrentRun(): Promise<Run | null> {
  const data = await chrome.storage.local.get([RUN_KEY]);
  return data[RUN_KEY] ?? null;
}

export async function setCurrentRun(run: Run | null) {
  if (run) {
    await chrome.storage.local.set({ [RUN_KEY]: run });
  } else {
    await chrome.storage.local.remove([RUN_KEY]);
  }
}

export async function ensureRun(): Promise<Run> {
  const existing = await getCurrentRun();
  if (existing) return existing;
  const run: Run = {
    runId: crypto.randomUUID(),
    startedAt: Date.now(),
    steps: []
  };
  await setCurrentRun(run);
  return run;
}

export async function pushStep(step: Step) {
  const run = await ensureRun();
  run.steps.push(step);
  await setCurrentRun(run);
}

export async function finalizeRun(): Promise<Run | null> {
  const run = await getCurrentRun();
  if (!run) return null;
  run.stoppedAt = Date.now();
  await setCurrentRun(run);
  return run;
}
